import fs from 'node:fs/promises';
import path from 'node:path';
import YAML from 'yaml';

const HTTP_METHODS = new Set([
  'get',
  'put',
  'post',
  'delete',
  'options',
  'head',
  'patch',
  'trace',
]);

const ALLOWED_MODULE_TOP_KEYS = new Set(['paths', 'components']);

const GENERATED_HEADER = [
  '# Code generated by tools/merge-openapi. DO NOT EDIT DIRECTLY.',
  '# Edit openapi/openapi.root.yaml or openapi/modules/*.yaml and run:',
  '#   pnpm --filter tools openapi:bundle',
  '',
].join('\n');

/**
 * Check whether a value is a non-null plain object (YAML mapping).
 * @param {unknown} value
 * @returns {value is Record<string, unknown>}
 */
function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Parse a YAML file with strict duplicate-key detection.
 * @param {string} filePath
 * @returns {Promise<Record<string, unknown>>}
 */
async function readYamlMapping(filePath) {
  const raw = await fs.readFile(filePath, 'utf8');
  let parsed;
  try {
    parsed = YAML.parse(raw, { uniqueKeys: true });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid YAML in ${filePath}: ${message}`);
  }

  if (parsed === null || parsed === undefined) {
    return {};
  }
  if (!isPlainObject(parsed)) {
    throw new Error(`Expected top-level YAML mapping in ${filePath}`);
  }
  return parsed;
}

/**
 * Record entries from a source mapping into a target mapping, failing on duplicates.
 * @param {object} params
 * @param {Record<string, unknown>} params.target
 * @param {Map<string, string>} params.owners
 * @param {unknown} params.source
 * @param {string} params.sourceLabel
 * @param {string} params.kindLabel
 */
function mergeUniqueMapping({ target, owners, source, sourceLabel, kindLabel }) {
  if (source === undefined || source === null) {
    return;
  }
  if (!isPlainObject(source)) {
    throw new Error(`Expected mapping for ${kindLabel} in ${sourceLabel}`);
  }

  for (const [key, value] of Object.entries(source)) {
    const existingOwner = owners.get(key);
    if (existingOwner !== undefined) {
      throw new Error(
        `Duplicate ${kindLabel} "${key}" defined in both ${existingOwner} and ${sourceLabel}`
      );
    }
    owners.set(key, sourceLabel);
    target[key] = value;
  }
}

/**
 * Merge all `components.*` subsections cleanly while rejecting duplicate component names.
 * @param {object} params
 * @param {Record<string, Record<string, unknown>>} params.targetComponents
 * @param {Map<string, Map<string, string>>} params.componentOwners
 * @param {unknown} params.sourceComponents
 * @param {string} params.sourceLabel
 */
function mergeComponents({ targetComponents, componentOwners, sourceComponents, sourceLabel }) {
  if (sourceComponents === undefined || sourceComponents === null) {
    return;
  }
  if (!isPlainObject(sourceComponents)) {
    throw new Error(`Expected mapping for components in ${sourceLabel}`);
  }

  for (const [section, entries] of Object.entries(sourceComponents)) {
    if (!targetComponents[section]) {
      targetComponents[section] = {};
    }
    let sectionOwners = componentOwners.get(section);
    if (!sectionOwners) {
      sectionOwners = new Map();
      componentOwners.set(section, sectionOwners);
    }

    mergeUniqueMapping({
      target: targetComponents[section],
      owners: sectionOwners,
      source: entries,
      sourceLabel,
      kindLabel: `components.${section}`,
    });
  }
}

/**
 * Ensure no two operations across the merged spec share the same `operationId`.
 * @param {object} params
 * @param {unknown} params.pathsObj
 * @param {string} params.sourceLabel
 * @param {Map<string, string>} params.operationOwners
 */
function trackOperationIds({ pathsObj, sourceLabel, operationOwners }) {
  if (!isPlainObject(pathsObj)) {
    return;
  }

  for (const [routePath, pathItem] of Object.entries(pathsObj)) {
    if (!isPlainObject(pathItem)) {
      continue;
    }
    for (const [method, operation] of Object.entries(pathItem)) {
      if (!HTTP_METHODS.has(method.toLowerCase()) || !isPlainObject(operation)) {
        continue;
      }
      const { operationId } = operation;
      if (typeof operationId !== 'string' || operationId.length === 0) {
        continue;
      }
      const location = `${sourceLabel} (${method.toUpperCase()} ${routePath})`;
      const existing = operationOwners.get(operationId);
      if (existing !== undefined) {
        throw new Error(
          `Duplicate operationId "${operationId}" in ${existing} and ${location}`
        );
      }
      operationOwners.set(operationId, location);
    }
  }
}

/**
 * Recursively verify that all local `#/components/<section>/<name>` refs exist.
 * @param {unknown} node
 * @param {Record<string, Record<string, unknown>>} components
 * @param {string} pointer
 */
function validateComponentRefs(node, components, pointer = '#') {
  if (Array.isArray(node)) {
    node.forEach((item, index) => validateComponentRefs(item, components, `${pointer}[${index}]`));
    return;
  }
  if (!isPlainObject(node)) {
    return;
  }

  if (typeof node.$ref === 'string' && node.$ref.startsWith('#/')) {
    const parts = node.$ref.slice(2).split('/');
    if (parts[0] === 'components' && parts.length === 3) {
      const [, section, name] = parts;
      if (!components?.[section] || !(name in components[section])) {
        throw new Error(`Unresolved $ref "${node.$ref}" at ${pointer}`);
      }
    }
  }

  for (const [key, value] of Object.entries(node)) {
    validateComponentRefs(value, components, `${pointer}.${key}`);
  }
}

/**
 * List sorted module YAML files inside `modulesDir`.
 * @param {string} modulesDir
 * @returns {Promise<string[]>}
 */
async function listModuleFiles(modulesDir) {
  let entries;
  try {
    entries = await fs.readdir(modulesDir, { withFileTypes: true });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Failed to read OpenAPI modules directory ${modulesDir}: ${message}`);
  }

  const files = entries
    .filter((entry) => entry.isFile() && /\.(yaml|yml)$/i.test(entry.name))
    .map((entry) => entry.name)
    .sort();

  if (files.length === 0) {
    throw new Error(`No module OpenAPI files (*.yaml) found in ${modulesDir}`);
  }

  return files;
}

/**
 * Render merged OpenAPI document to deterministic LF YAML with header banner.
 * @param {Record<string, unknown>} doc
 * @returns {string}
 */
function renderBundledYaml(doc) {
  const body = YAML.stringify(doc, {
    lineWidth: 120,
    aliasDuplicateObjects: false,
  }).replace(/\r\n/g, '\n');

  const normalizedBody = body.endsWith('\n') ? body : `${body}\n`;
  return `${GENERATED_HEADER}${normalizedBody}`;
}

/**
 * Merge `openapi.root.yaml` and `modules/*.yaml` into a bundled OpenAPI document.
 * Throws on duplicate paths, duplicate components, duplicate operationIds, or broken refs.
 * @param {object} options
 * @param {string} options.rootPath
 * @param {string} options.modulesDir
 * @param {string} [options.outputPath]
 * @param {boolean} [options.write=true]
 * @param {boolean} [options.check=false]
 * @returns {Promise<{
 *   document: Record<string, unknown>,
 *   yaml: string,
 *   moduleCount: number,
 *   pathCount: number,
 *   schemaCount: number,
 *   inSync: boolean | null
 * }>}
 */
export async function mergeOpenApi({
  rootPath,
  modulesDir,
  outputPath,
  write = true,
  check = false,
}) {
  const rootDoc = await readYamlMapping(rootPath);
  const rootLabel = path.basename(rootPath);
  const moduleFiles = await listModuleFiles(modulesDir);

  const mergedPaths = {};
  const pathOwners = new Map();
  const mergedComponents = {};
  const componentOwners = new Map();
  const operationOwners = new Map();

  mergeUniqueMapping({
    target: mergedPaths,
    owners: pathOwners,
    source: rootDoc.paths,
    sourceLabel: rootLabel,
    kindLabel: 'path',
  });
  trackOperationIds({
    pathsObj: rootDoc.paths,
    sourceLabel: rootLabel,
    operationOwners,
  });
  mergeComponents({
    targetComponents: mergedComponents,
    componentOwners,
    sourceComponents: rootDoc.components,
    sourceLabel: rootLabel,
  });

  for (const fileName of moduleFiles) {
    const filePath = path.join(modulesDir, fileName);
    const sourceLabel = `modules/${fileName}`;
    const moduleDoc = await readYamlMapping(filePath);

    for (const key of Object.keys(moduleDoc)) {
      if (!ALLOWED_MODULE_TOP_KEYS.has(key)) {
        throw new Error(
          `Unexpected top-level key "${key}" in ${sourceLabel}; only "paths" and "components" are allowed`
        );
      }
    }

    mergeUniqueMapping({
      target: mergedPaths,
      owners: pathOwners,
      source: moduleDoc.paths,
      sourceLabel,
      kindLabel: 'path',
    });
    trackOperationIds({
      pathsObj: moduleDoc.paths,
      sourceLabel,
      operationOwners,
    });
    mergeComponents({
      targetComponents: mergedComponents,
      componentOwners,
      sourceComponents: moduleDoc.components,
      sourceLabel,
    });
  }

  const mergedDoc = {
    ...rootDoc,
    paths: mergedPaths,
    components: mergedComponents,
  };

  validateComponentRefs(mergedDoc, mergedComponents);

  const rendered = renderBundledYaml(mergedDoc);
  let inSync = null;

  if (check) {
    if (!outputPath) {
      throw new Error('outputPath is required when check=true');
    }
    let existing = null;
    try {
      existing = (await fs.readFile(outputPath, 'utf8')).replace(/\r\n/g, '\n');
    } catch (error) {
      if (error?.code !== 'ENOENT') {
        throw error;
      }
    }
    inSync = existing === rendered;
    if (!inSync) {
      throw new Error(
        `${outputPath} is out of date with openapi/openapi.root.yaml and openapi/modules/*.yaml. Run: pnpm --filter tools openapi:bundle`
      );
    }
  } else if (write) {
    if (!outputPath) {
      throw new Error('outputPath is required when write=true');
    }
    await fs.mkdir(path.dirname(outputPath), { recursive: true });
    await fs.writeFile(outputPath, rendered, 'utf8');
  }

  return {
    document: mergedDoc,
    yaml: rendered,
    moduleCount: moduleFiles.length,
    pathCount: Object.keys(mergedPaths).length,
    schemaCount: Object.keys(mergedComponents.schemas ?? {}).length,
    inSync,
  };
}

